if x
  lambda { _1 }
else
  -> { _1 }
end

if x
  lambda { it }
else
  -> { it }
end

if x
  lambda() { |a| a }
else
  ->(a) { a }
end

if x
  foo { || work }
else
  foo { work }
end

if x
  foo { while a; b; end }
else
  foo { b while a }
end

if x
  foo { def self.f(a); a; end }
else
  foo { def self.f(a) = a }
end
